import telemetry_nerd.tn as tn, polars as pl, json
from datetime import datetime, timezone
for h,key in [("d8","span_name"),("d7","service_name")]:
    df=tn.dataset(h); s=tn.dataset(h,"series")
    lab={r["series_id"]:(json.loads(r["labels"]) if isinstance(r["labels"],str) else r["labels"])[key] for r in s.to_dicts()}
    for sid,n in lab.items():
        if h=="d7" and n not in ("frontend","checkout","shipping"): continue
        d=df.filter((pl.col("series_id")==sid)&pl.col("avg").is_not_null()).sort("ts_ms")
        print(h,n," ".join(f"{datetime.fromtimestamp(t/1000,timezone.utc).strftime('%H:%M')}={a:.2f}" for t,a in zip(d["ts_ms"],d["avg"]) if t>=1.7753e12*0 and datetime.fromtimestamp(t/1000,timezone.utc).strftime('%H:%M')>='21:40'))
